class Counter:
    def __init__(self, start=0):
        self.count = start

    def bump(self):
        self.count += 1
        return self.count


c = Counter(5)
print(c.bump(), c.bump(), c.count)

class ConfigError(Exception):
    def __init__(self, message, line):
        super().__init__(f"line {line}: {message}")
        self.line = line


try:
    raise ConfigError("bad value", 7)
except ConfigError as e:
    print(e, "|", e.line)
